export type TimedEvent = {
  type: "turn" | "pace_change" | "pause" | "loop";
  audio_offset_ms: number;
};

const SAMPLE_RATE = 16000;

export function pauseWindow(
  events: TimedEvent[],
  durationMs: number,
): { startMs: number; endMs: number } | null {
  const pause = events.find((event) => event.type === "pause");
  if (!pause) return null;
  const next = events
    .map((event) => event.audio_offset_ms)
    .filter((offset) => offset > pause.audio_offset_ms)
    .sort((left, right) => left - right)[0];
  const endMs = Math.min(durationMs, next ?? pause.audio_offset_ms + 10_000);
  return { startMs: pause.audio_offset_ms, endMs };
}

export function sketchFrequencyHz(
  timeMs: number,
  turnMs: number,
  pauseStartMs: number,
  pauseEndMs: number,
): number {
  if (timeMs >= pauseStartMs && timeMs < pauseEndMs) return 0;
  if (timeMs < turnMs) {
    const progress = turnMs === 0 ? 1 : timeMs / turnMs;
    return 523 - progress * (523 - 330);
  }
  if (timeMs < pauseStartMs) {
    const span = Math.max(pauseStartMs - turnMs, 1);
    const progress = Math.min((timeMs - turnMs) / span, 1);
    return 330 + progress * (523 - 330);
  }
  return 392;
}

export function synthesizeSketchWav(durationMs: number, events: TimedEvent[]): Uint8Array {
  const turnMs = events.find((event) => event.type === "turn")?.audio_offset_ms ?? durationMs;
  const pause = pauseWindow(events, durationMs) ?? { startMs: durationMs, endMs: durationMs };
  const sampleCount = Math.floor((SAMPLE_RATE * durationMs) / 1000);
  const bytes = new Uint8Array(44 + sampleCount * 2);
  const view = new DataView(bytes.buffer);
  writeAscii(bytes, 0, "RIFF");
  view.setUint32(4, 36 + sampleCount * 2, true);
  writeAscii(bytes, 8, "WAVE");
  writeAscii(bytes, 12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, SAMPLE_RATE, true);
  view.setUint32(28, SAMPLE_RATE * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  writeAscii(bytes, 36, "data");
  view.setUint32(40, sampleCount * 2, true);

  let phase = 0;
  for (let index = 0; index < sampleCount; index += 1) {
    const timeMs = (index / SAMPLE_RATE) * 1000;
    const frequency = sketchFrequencyHz(timeMs, turnMs, pause.startMs, pause.endMs);
    const amplitude = frequency === 0 ? 0 : Math.sin(phase) * 0.35;
    phase += (2 * Math.PI * frequency) / SAMPLE_RATE;
    view.setInt16(44 + index * 2, Math.round(amplitude * 32767), true);
  }
  return bytes;
}

export function meanAbsoluteSample(
  wav: Uint8Array,
  startMs: number,
  endMs: number,
): number {
  const view = new DataView(wav.buffer, wav.byteOffset, wav.byteLength);
  const start = Math.max(0, Math.floor((SAMPLE_RATE * startMs) / 1000));
  const end = Math.min(Math.floor((SAMPLE_RATE * endMs) / 1000), (wav.byteLength - 44) / 2);
  if (end <= start) return 0;
  let total = 0;
  for (let index = start; index < end; index += 1) {
    total += Math.abs(view.getInt16(44 + index * 2, true));
  }
  return total / (end - start);
}

function writeAscii(bytes: Uint8Array, offset: number, value: string): void {
  for (let index = 0; index < value.length; index += 1) {
    bytes[offset + index] = value.charCodeAt(index);
  }
}

import type { RoutePoint } from "../contracts/types";

export function pointOnRoute(points: RoutePoint[], timeMs: number): RoutePoint {
  const first = points[0];
  if (!first) return { x: 0, y: 0, t_ms: 0 };
  if (timeMs <= first.t_ms) return { ...first, t_ms: timeMs };
  for (let index = 1; index < points.length; index += 1) {
    const previous = points[index - 1];
    const next = points[index];
    if (!previous || !next || timeMs > next.t_ms) continue;
    const span = next.t_ms - previous.t_ms;
    const mix = span === 0 ? 0 : (timeMs - previous.t_ms) / span;
    return {
      x: previous.x + (next.x - previous.x) * mix,
      y: previous.y + (next.y - previous.y) * mix,
      t_ms: timeMs,
    };
  }
  const last = points[points.length - 1] ?? first;
  return { ...last, t_ms: timeMs };
}

import { useEffect, useRef, useState } from "react";

export function useAudioClock(source: string, durationMs: number) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [timeMs, setTimeMs] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [playbackError, setPlaybackError] = useState<string | null>(null);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    let frame = 0;
    const readClock = () => setTimeMs(Math.round(audio.currentTime * 1000));
    const tick = () => {
      readClock();
      if (!audio.paused) frame = requestAnimationFrame(tick);
    };
    const onPlay = () => {
      setPlaying(true);
      setPlaybackError(null);
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(tick);
    };
    const onPause = () => {
      setPlaying(false);
      cancelAnimationFrame(frame);
      readClock();
    };
    audio.addEventListener("play", onPlay);
    audio.addEventListener("pause", onPause);
    audio.addEventListener("ended", onPause);
    return () => {
      cancelAnimationFrame(frame);
      audio.removeEventListener("play", onPlay);
      audio.removeEventListener("pause", onPause);
      audio.removeEventListener("ended", onPause);
    };
  }, [source]);

  const seek = (nextMs: number) => {
    const bounded = Math.min(durationMs, Math.max(0, nextMs));
    const audio = audioRef.current;
    if (audio) audio.currentTime = bounded / 1000;
    setTimeMs(Math.round(bounded));
  };

  const toggle = () => {
    const audio = audioRef.current;
    if (!audio) return;
    if (audio.paused) {
      void audio.play().catch(() => {
        setPlaybackError("Playback did not start. Press Play to try again.");
      });
      return;
    }
    audio.pause();
  };

  return { audioRef, timeMs, playing, playbackError, seek, toggle };
}

export function SoundprintPlayer({
  source,
  durationMs,
  timeMs,
  playing,
  playbackError,
  audioRef,
  onToggle,
  onSeek,
}: {
  source: string;
  durationMs: number;
  timeMs: number;
  playing: boolean;
  playbackError: string | null;
  audioRef: React.RefObject<HTMLAudioElement | null>;
  onToggle: () => void;
  onSeek: (timeMs: number) => void;
}) {
  return (
    <section className="player panel" aria-labelledby="player-title">
      <h2 id="player-title">Playback</h2>
      <p>
        Deterministic sketch generated in the browser. The tone falls until the corner, then rises.
        The hold is silent. This is not ElevenLabs audio.
      </p>
      <div className="player-controls">
        <button type="button" className="action" onClick={onToggle}>
          {playing ? "Pause" : "Play"}
        </button>
        <span className="mono">
          {formatClock(timeMs)} / {formatClock(durationMs)}
        </span>
      </div>
      <input
        className="scrubber"
        type="range"
        min={0}
        max={durationMs}
        step={100}
        value={timeMs}
        aria-label="Scrub Soundprint"
        onInput={(event) => onSeek(Number(event.currentTarget.value))}
      />
      {playbackError ? <p role="alert">{playbackError}</p> : null}
      <audio ref={audioRef} src={source} preload="auto" />
    </section>
  );
}

function formatClock(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${seconds.toString().padStart(2, "0")}`;
}

