input.contents:
import type { ReactNode } from "react";

export function StateMessage({
  title,
  tone,
  children,
}: {
  title: string;
  tone: "status" | "alert";
  children: ReactNode;
}) {
  return (
    <section
      className={tone === "alert" ? "notice" : "panel"}
      role={tone}
      aria-labelledby="preview-state-title"
    >
      <h2 id="preview-state-title">{title}</h2>
      {children}
    </section>
  );
}

export function StatePicker<T extends string>({
  legend,
  note,
  options,
  value,
  onChange,
}: {
  legend: string;
  note: string;
  options: readonly { id: T; label: string }[];
  value: T;
  onChange: (id: T) => void;
}) {
  return (
    <fieldset className="state-picker">
      <legend>{legend}</legend>
      <p className="muted">{note}</p>
      <div className="state-picker-options">
        {options.map((option) => (
          <button
            key={option.id}
            type="button"
            aria-pressed={value === option.id}
            onClick={() => onChange(option.id)}
          >
            {option.label}
          </button>
        ))}
      </div>
    </fieldset>
  );
}

import { useState } from "react";
import { StateMessage } from "../components/StateMessage";
import { StatePicker } from "../components/StatePicker";

const WALK_STATES = [
  { id: "empty", label: "Empty" },
  { id: "permission", label: "Permission" },
  { id: "loading", label: "Waiting for position" },
  { id: "invalid", label: "Invalid trace" },
  { id: "interrupted", label: "Page hidden" },
] as const;

type WalkStateId = (typeof WALK_STATES)[number]["id"];

type WalkScreenProps = {
  onNavigate: (event: { preventDefault: () => void; currentTarget: { href: string } }) => void;
};

export function WalkScreen({ onNavigate }: WalkScreenProps) {
  const [state, setState] = useState<WalkStateId>("empty");
  return (
    <div className="stack">
      <section className="stack" aria-labelledby="walk-title">
        <h1 id="walk-title">Footwork</h1>
        <p className="lede">
          A recorded walk becomes a short instrumental piece and a Soundprint that moves with it. A
          sharp turn is meant to change the melody&apos;s direction. A pause is meant to become a
          musical break.
        </p>
        <div className="actions">
          <a className="action" href="/studio" onClick={onNavigate}>
            Play example
          </a>
          <a className="action secondary" href="/about" onClick={onNavigate}>
            How it works
          </a>
        </div>
      </section>
      <StatePicker
        legend="Recording preview"
        note="These states are a fixture. They do not request location or store a walk."
        options={WALK_STATES}
        value={state}
        onChange={setState}
      />
      {state === "empty" ? (
        <section className="panel" aria-labelledby="recording-title">
          <h2 id="recording-title">Recording</h2>
          <p>No walk is stored on this device.</p>
          <p className="muted">
            Duration and signal quality appear here only after a real recording starts. This
            preview does not request location access.
          </p>
        </section>
      ) : null}
      {state === "permission" ? (
        <StateMessage title="Permission" tone="alert">
          <p>Location access was denied.</p>
          <p>
            In the browser settings for this site, allow location, then return and start again.
            This preview did not open a location prompt.
          </p>
          <p>
            <a className="action" href="/studio" onClick={onNavigate}>
              Play example
            </a>
          </p>
        </StateMessage>
      ) : null}
      {state === "loading" ? (
        <StateMessage title="Waiting for position" tone="status">
          <p>Waiting for a position fix.</p>
          <p>Duration and signal stay blank until a real fix arrives. This preview is not locating you.</p>
        </StateMessage>
      ) : null}
      {state === "invalid" ? (
        <StateMessage title="Invalid trace" tone="alert">
          <p>
            This trace cannot become a Soundprint. The movement was too short and the position
            quality was too poor to score. No events were invented.
          </p>
          <p>
            <a className="action" href="/studio" onClick={onNavigate}>
              Play example
            </a>
          </p>
        </StateMessage>
      ) : null}
      {state === "interrupted" ? (
        <StateMessage title="Page hidden" tone="alert">
          <p>
            The page was in the background. The gap is marked, and no positions were filled in.
          </p>
          <p>Return to this tab before recording continues. This preview is not recording.</p>
        </StateMessage>
      ) : null}
    </div>
  );
}

import { StateMessage } from "../components/StateMessage";

export const GENERATION_STATES = [
  { id: "fixture", label: "Synthetic fixture" },
  { id: "loading", label: "Processing" },
  { id: "partial", label: "Partial" },
  { id: "quota", label: "Quota" },
  { id: "provider", label: "Provider failure" },
] as const;

export type GenerationStateId = (typeof GENERATION_STATES)[number]["id"];

export function GenerationStateBody({
  state,
  onShowFixture,
}: {
  state: Exclude<GenerationStateId, "fixture">;
  onShowFixture: () => void;
}) {
  if (state === "loading") {
    return (
      <StateMessage title="Processing" tone="status">
        <p>This preview is not running generation and did not call a provider.</p>
        <ol>
          <li>Processing movement</li>
          <li>Arranging</li>
          <li>Composing</li>
        </ol>
      </StateMessage>
    );
  }
  if (state === "partial") {
    return (
      <StateMessage title="Partial" tone="status">
        <p>
          Partial result. The trace can be shown, but it does not contain enough event variety.
          Absent mappings stay absent. This is not a completed Studio Track.
        </p>
        <p>
          <button className="action" type="button" onClick={onShowFixture}>
            Show the synthetic example
          </button>
        </p>
      </StateMessage>
    );
  }
  if (state === "quota") {
    return (
      <StateMessage title="Quota" tone="alert">
        <p>
          Daily generation limit reached. Try again after the limit resets. No account balance is
          shown. A Route Sketch and the separate example stay available.
        </p>
        <p>
          <button className="action" type="button" onClick={onShowFixture}>
            Show the synthetic example
          </button>
        </p>
      </StateMessage>
    );
  }
  return (
    <StateMessage title="Provider failure" tone="alert">
      <p>Arrangement service unavailable; creating Route Sketch.</p>
      <p>Studio generation unavailable; your movement sketch is ready.</p>
      <p>This preview did not call Gemma or ElevenLabs, and it did not produce a Studio Track.</p>
      <p>
        <button className="action" type="button" onClick={onShowFixture}>
          Show the synthetic example
        </button>
      </p>
    </StateMessage>
  );
}

